import ast,sys
for f in sys.argv[1:]:
    for n in ast.walk(ast.parse(open(f).read())):
        if isinstance(n,(ast.FunctionDef,)):
            print(f, n.name, n.end_lineno-n.lineno+1 + (n.lineno-n.lineno))
' hourglass/timesheet.py tests/test_timesheet.py; echo "--- trailing commas:"; for f in hourglass/timesheet.py tests/test_timesheet.py; do awk -v f=$f '/,[[:space:]]*$/ {last=FNR; txt=$0} /^[[:space:]]*[]})]/ && last==FNR-1 {print f": "FNR-1": "txt}' $f; done; echo "--- import order:"; sed -n '3,7p' hourglass/timesheet.py; sed -n 1,4p tests/test_timesheet.py

